    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not distinguish exclusion of studies because outcomes were not measured from exclusion because outcome results were not reported; exclusion reasons listed are study-design/population based only."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "HRs were not entered into synthesis unless the comparison isolated hepatectomy versus nonhepatectomy management.",
      "reason": "Synthesis groups are clearly specified as hepatectomy versus non-hepatectomy comparisons, with endpoint-specific groupings (OS vs PFS/EFS estimates, per text_12) linked to the review's target contrast defined in the objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Initially unresectable disease was accepted according to the original study definition, protocol designation, or multidisciplinary treatment context [37]. We did not retrospectively impose a uniform technical unresectability definition across heterogeneous published cohorts.",
      "reason": "Rationales for notable eligibility decisions are provided, including accepting original unresectability definitions due to cohort heterogeneity, and text_10 explains why regimen-based subgroup analyses were not planned."
    }
  ],
  "confidence": 88
}

